print("Active study minutes?")
active_text = input()
active_minutes = int(active_text)
print("Break minutes?")
break_text = input()
break_minutes = int(break_text)

if active_minutes < 0:
    print("Invalid: active minutes cannot be negative.")
elif active_minutes > 1440:
    print("Invalid: active minutes exceed the planning window.")
elif break_minutes < 0:
    print("Invalid: break minutes cannot be negative.")
elif break_minutes > 1440:
    print("Invalid: break minutes exceed the planning window.")
elif active_minutes + break_minutes > 1440:
    print("Invalid: combined time exceeds the planning window.")
else:
    elapsed_minutes = active_minutes + break_minutes
    print("Elapsed time:", elapsed_minutes // 60, "h", elapsed_minutes % 60, "min")
    if active_minutes < 360:
        print("Below target by", 360 - active_minutes, "active minutes.")
    elif active_minutes == 360:
        print("Exactly at the 360-minute active-study target.")
    else:
        print("Above target by", active_minutes - 360, "active minutes.")

